.quiet-center {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  color: var(--star-dim);
  font-size: 22px;
  font-weight: 300;
  padding: 24px;
  margin: 0;
  z-index: 2;
}
.finished-line {
  position: absolute;
  top: 52px;
  left: 0;
  right: 250px;
  text-align: center;
  margin: 0;
  font-size: 28px;
  font-weight: 300;
  color: var(--star);
  animation: fadeIn 1.2s ease forwards;
  z-index: 3;
