window.BlackoutObserver = (function () {
  const MIC_LABELS = {
    listening: "在听",
    paused: "暂停",
    user_speaking: "你在说",
    ai_speaking: "AI 在说",
    offline: "未连接"
  };
  const ACTION_LABELS = {
    listen: "听着，没打断",
    follow_up: "追问没说完的点",
    pull_back: "拉回主线",
    continue: "推进",
    answer: "回答",
    summarize: "确认结束"
  };
  const POSTER_WAIT_LIMIT_MS = 3 * 60 * 1000;
  let sessionId = "";
  let timer = 0;
  let subtitleTimer = 0;
  let lastParkingJson = "";
  let parkingSeen = false;
  let lastSubtitleText = "";
  let finishedAt = 0;
  let posterShown = false;
  function el(id) {
    return document.getElementById(id);
  }
  function sessionParam() {
    try {
      return new URLSearchParams(window.location.search).get("session") || "";
    } catch (e) {
      return "";
    }
  }
  function showMessage(text) {
    const node = el("obsMessage");
    node.textContent = String(text || "");
    node.hidden = !text;
  }
  function armSubtitleFade(text) {
    if (text === lastSubtitleText) {
      return;
    }
    lastSubtitleText = text;
    const box = el("obsSubtitles");
    if (box) {
      box.classList.remove("faded");
    }
    window.clearTimeout(subtitleTimer);
    subtitleTimer = window.setTimeout(function () {
      if (box) {
        box.classList.add("faded");
      }
    }, 8000);
  }
  function renderParking(parking) {
    const list = el("obsParking");
    const items = parking || [];
    const json = JSON.stringify(items);
    const isNew = parkingSeen && json !== lastParkingJson;
    list.replaceChildren();
    items.forEach(function (item, index) {
      const li = document.createElement("li");
      li.textContent = String(item || "");
      if (isNew && index === items.length - 1) {
        li.className = "new";
      }
      list.appendChild(li);
    });
    parkingSeen = true;
    lastParkingJson = json;
  }
  function resultOf(record) {
    const result = record && record.result;
    return result && typeof result === "object" ? result : {};
  }
  function posterOf(record) {
    const resultPoster = resultOf(record).poster;
    if (resultPoster && typeof resultPoster === "object") {
      return resultPoster;
    }
    const recordPoster = record && record.poster;
    if (recordPoster && typeof recordPoster === "object") {
      return recordPoster;
    }
    return {};
  }
  function posterStatusOf(record) {
    return String(posterOf(record).status || "");
  }
  function titleOf(record) {
    const title = resultOf(record).title;
    return title ? String(title) : "成果";
  }
  function mapOf(record) {
    const resultMap = resultOf(record).map;
    if (record && record.status === "finished" && resultMap) {
      return resultMap;
    }
    return record ? record.map : null;
  }
  function renderMap(record) {
    if (!window.BlackoutMap || !record) {
      return;
    }
    const tree = mapOf(record);
    if (!tree) {
      return;
    }
    const svg = el("obsMap");
    if (!svg) {
      return;
    }
    svg.setAttribute("preserveAspectRatio", "xMidYMid meet");
    window.BlackoutMap.render(svg, tree, { theme: "night", animate: true });
    svg.classList.add("map");
    svg.classList.add("map-night");
    svg.setAttribute("preserveAspectRatio", "xMidYMid meet");
  }
  function renderDecision(action, reason, reply) {
    let decision = "";
    if (action === "listen") {
      decision = "听着，没打断";
    } else if (action) {
      decision = (ACTION_LABELS[action] || action) + (reason ? " · " + reason : "");
    }
    el("obsDecision").textContent = reply ? decision : decision;
  }
  function renderSession(record, live) {
    const state = (record && record.state) || {};
    renderMap(record);
    const micKey = Object.prototype.hasOwnProperty.call(MIC_LABELS, live.mic) ? live.mic : "offline";
    const micNode = el("obsMic");
    micNode.textContent = MIC_LABELS[micKey];
    micNode.className = "corner corner-right" + (micKey === "ai_speaking" ? " mic-ai" : "");
    const caption = String(live.partial || live.last_user || "");
    el("obsCaption").textContent = caption;
    const reply = String(live.last_reply || "");
    el("obsReply").textContent = reply;
    const action = String(live.last_action || "");
    const reason = String(live.last_reason || "");
    renderDecision(action, reason, reply);
    armSubtitleFade(caption + "|" + reply + "|" + action + "|" + reason);
    renderParking(state.parking_lot || []);
    const stats = record.stats || {};
    const turns = String(stats.user_turns || 0);
    const spoke = String(stats.ai_spoke || 0);
    const pullBacks = String(stats.pull_backs || 0);
    el("obsCounters").textContent = "说了 " + turns + " 句 · 开口 " + spoke + " 次 · 拉回 " + pullBacks + " 次";
  }
  function stopPolling() {
    window.clearInterval(timer);
    timer = 0;
  }
  function showPoster(record) {
    if (posterShown) {
      return;
    }
    posterShown = true;
    const poster = posterOf(record);
    const version = poster.version;
    let src = "/api/sessions/" + sessionId + "/poster";
    if (typeof version === "number" || typeof version === "string") {
      src += "?v=" + encodeURIComponent(String(version));
    }
    const image = el("posterImage");
    image.src = src;
    el("posterTitle").textContent = "灯亮了 · " + titleOf(record);
    const banner = el("obsFinished");
    banner.hidden = true;
    const subtitles = el("obsSubtitles");
    if (subtitles) {
      subtitles.hidden = true;
    }
    const parkingPanel = el("obsParkingPanel");
    if (parkingPanel) {
      parkingPanel.hidden = true;
    }
    const svg = el("obsMap");
    if (svg) {
      svg.classList.add("map-faded");
    }
    window.clearTimeout(subtitleTimer);
    const wrap = el("posterWrap");
    wrap.hidden = false;
    window.requestAnimationFrame(function () {
      wrap.classList.add("visible");
    });
    stopPolling();
  }
  function handleFinished(record, live) {
    if (!finishedAt) {
      finishedAt = Date.now();
    }
    renderSession(record, live || {});
    el("obsMic").textContent = MIC_LABELS.offline;
    const banner = el("obsFinished");
    banner.textContent = "灯亮了 · " + titleOf(record);
    banner.hidden = false;
    const status = posterStatusOf(record);
    if (status === "done") {
      showPoster(record);
      return;
    }
    if (status === "failed") {
      stopPolling();
      return;
    }
    if (Date.now() - finishedAt >= POSTER_WAIT_LIMIT_MS) {
      stopPolling();
    }
  }
  async function fetchJson(url) {
    const response = await fetch(url);
    const data = await response.json();
    if (!response.ok) {
      const message = (data && data.error && data.error.message) || "加载失败。";
      throw new Error(String(message));
    }
    return data;
  }
  async function pollOnce() {
    if (!sessionId) {
      return;
    }
    let record = null;
    try {
      record = await fetchJson("/api/sessions/" + sessionId);
    } catch (e) {
      const message = "还没有指定要看的星图。从开始页勾选“录视频：同时打开星图窗口”再开始。";
      showMessage(message);
      stopPolling();
      return;
    }
    let live = {};
    try {
      live = await fetchJson("/api/sessions/" + sessionId + "/live");
    } catch (e) {}
    if (record.status === "finished") {
      handleFinished(record, live || {});
      return;
    }
    renderSession(record, live || {});
  }
  function init() {
    sessionId = sessionParam();
    if (!/^[0-9a-f]{32}$/.test(sessionId)) {
      const message = "还没有指定要看的星图。从开始页勾选“录视频：同时打开星图窗口”再开始。";
      showMessage(message);
      return;
    }
    pollOnce();
    timer = window.setInterval(pollOnce, 1000);
  }
  document.addEventListener("DOMContentLoaded", init);
  return { init: init, pollOnce: pollOnce };
})();
