    const nodes = [];
    const nodesById = {};
    placeNode(tree, 0, -Math.PI / 2, Math.PI * 1.5, null, radii, nodes, nodesById);
    resolveLabelCollisions(nodes);
    return { nodes: nodes, byId: nodesById, radii: radii };
  }
